select public.admin_notify('🧩 Unified login + Business portfolio guide', 'Dashboard Customize screen: do setup options — "API setup with Unified login" (yahi chahiye; Instagram Login isme hai) aur "Facebook login" (Page mangta hai, skip). Unified login ke liye Business portfolio mandatory hai ⇒ owner ko guide: + Business portfolio → Create new "Mini eSports" (sirf business-container; koi Page/FB use nahi) → select → permissions me instagram_business_basic + manage_messages (+ content_publish, manage_comments) → save. Phir App Roles, Webhooks, App ID/Secret private Drive file.', 'session_end') as notified;
